import {basisDelivery} from './admin-order-attention.mjs';
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
const money=n=>(n/100).toLocaleString('da-DK',{style:'currency',currency:'DKK'});
const labels={review:'Afventer afsendelse',sending:'Afsendes – afstem før genforsøg',uncertain:'Udfald ukendt – kræver afstemning',sent:'Sendt',confirmed:'Bekræftet',failed:'Afvist',requested:'Afventer bekræftelse'};
export function financePanel(order,api,{onChanged=async()=>{}}={}){
 const root=el('details'),body=el('div'),feedback=el('p');root.append(el('summary','Betaling og fakturagrundlag'),body,feedback);feedback.setAttribute('role','status');
 if(!order.checkoutId){body.append(el('p','Ingen betalingsordre tilknyttet.'));return root;}
 const url=`/api/pf-orders/${order.id}/finance`;let loaded=false,busy=false;
 let verified=false;
 async function refreshPayment(){if(busy)return;busy=true;verified=false;feedback.textContent='Kontrollerer betalingsstatus hos Quickpay…';try{const result=await(await api(url,'POST',{action:'reconcile'})).json();if(result.error)throw Error(result.error);verified=true;feedback.textContent='Betalingsstatus kontrolleret · '+new Date().toLocaleTimeString('da-DK');}catch(e){feedback.textContent='Betalingsstatus kunne ikke kontrolleres: '+e.message+' Prøv Opdatér betalingsstatus.';}finally{busy=false;await load();}}
 root.ontoggle=()=>{if(root.open&&!loaded){loaded=true;refreshPayment();}};
 async function action(input){if(busy)return;busy=true;feedback.textContent='Behandler…';try{const result=await(await api(url,'POST',input)).json();if(result.error)throw Error(result.error);feedback.textContent='Registreret.';await load();try{await onChanged();}catch{feedback.textContent='Handlingen er registreret. Opdatér siden for at hente den nye status; gentag ikke handlingen.';}}catch(e){feedback.textContent=e.message;}finally{busy=false;}}
 function button(label,fn){const b=el('button',label);b.type='button';b.onclick=fn;return b;}
 function field(form,label,name,value='',type='text'){const l=el('label',label),i=el('input');i.name=name;i.type=type;i.value=value;i.required=true;l.append(i);form.append(l);return i;}
 async function load(){try{const data=await(await api(url)).json();body.replaceChildren();const s=data.summary;
  const overview=el('section');overview.className='finance-overview';
  const paid=s.captured>=s.ordered&&s.ordered>0,sent=basisDelivery(order.attention)||data.mail.find(m=>m.kind==='accountant_basis'&&m.status==='sent');
  overview.append(el('h3',paid?'Betalt – beløbet er hævet':s.captured>0?'Delvist hævet':'Betaling ikke registreret som hævet'),el('p','Hævet '+money(s.captured)+' af '+money(s.ordered)+(s.refunded?' · Refunderet '+money(s.refunded):'')));
  overview.append(el('p',sent?'Fakturagrundlag sendt til Financial Outsourcing.':data.shipments.some(m=>m.invoiceStatus==='issued')?'Faktura registreret fra Financial Outsourcing.':'Fakturagrundlag: afventer gennemgang og afsendelse.'));
  overview.append(el('p',!verified?'Kontrollér betalingsstatus før en hævning.':paid?'Betalingen er bekræftet. Financial Outsourcing håndterer bogføring og bankafstemning.':s.shipped===s.ordered&&s.ordered>0?'Ordren er afsendt. Hævning afventer behandling; se automatikstatus nedenfor.':'Betaling følger ordrens aftalte vilkår. Ved forudbetaling håndteres godkendelse og hævning under Korrektur.'));
  body.append(overview);
  body.append(el('p',data.configuration.enabled&&data.configuration.automaticCapture&&data.configuration.agreementConfirmed&&Number.isFinite(Date.parse(data.configuration.startAt))?'Automatisk hævning ved fuld afsendelse er aktiveret for omfattede ordrer. Forudbetaling følger korrekturflowet.':'Automatisk hævning kræver aktivering af økonomiflow, betalingsaftale og startdato i serveropsætningen.'));
  const accounting=el('details');accounting.append(el('summary','Bogholderi · bilag og bankafstemning'),el('p','Financial Outsourcing håndterer afstemningen i e-conomic. Felterne her bruges kun til manuel registrering i Smerch.'));

  accounting.append(el('p',`${data.policy.type==='simplified'?'Forenklet faktura':'Fuld faktura'} · Nummerering: ${data.configuration.numberingAuthority||'afventer Financial Outsourcing'}`));
  if(data.captureDeadline?.policy==='clearhaus-179-days'){body.append(el('p','Hævningsfrist hos Clearhaus: '+new Date(data.captureDeadline.at).toLocaleString('da-DK')+'. Bankens reservation kan udløbe tidligere.'));if(data.captureDeadline.lateCapture)body.append(el('p','Hævning efter syv dage: late capture-gebyr og øget risiko for indsigelser.'));}
  if(!data.configuration.enabled||!data.configuration.automationsEnabled)accounting.append(el('p','Automatisk afsendelse af bogholderbilag er slået fra. Betalingsstatus kontrolleres, når denne sektion åbnes.'));
  const stats=el('dl');stats.className='finance-totals';for(const [key,label] of [['ordered','Bestilt'],['shipped','Afsendt'],['remaining','Restordre'],['invoiced','Faktureret'],['credited','Krediteret'],['captured','Hævet'],['refunded','Refunderet'],['unsettled','Ikke afregnet før gebyrer'],['held','Tilbageholdt']])stats.append(el('dt',label),el('dd',money(s[key])));accounting.append(stats);
  for(const problem of s.problems)body.append(el('p',problem));
  body.append(button('Opdatér betalingsstatus',refreshPayment));
  if(verified&&s.ordered>0&&s.shipped===s.ordered&&s.captured===0&&!data.operations.some(o=>['requested','sending','uncertain'].includes(o.status)))body.append(button('Bekræft hævning · '+money(s.ordered),()=>{if(confirm('Hæv hele ordrebeløbet på '+money(s.ordered)+' efter bekræftet fuld afsendelse?'))action({action:'payment',kind:'capture',amount:s.ordered,key:'shipment-capture:'+s.ordered});}));
  const table=el('table');table.className='finance-table';const header=el('tr');for(const title of ['Leverance','Beløb','Fakturering','Handling'])header.append(el('th',title));table.append(header);
  for(const shipment of data.shipments){const row=el('tr');row.append(el('td',shipment.shipDate.slice(0,10)),el('td',money(shipment.total)),el('td',shipment.invoiceStatus==='issued'?'Faktura registreret':'Afventer bogholder'));const cell=el('td'),a=el('a','Hent fakturagrundlag');a.href=url+'?basis='+encodeURIComponent(shipment.key);cell.append(a);const sentBasis=basisDelivery(order.attention),queued=data.mail.find(m=>m.kind==='accountant_basis'&&m.shipmentKey===shipment.key&&['sent','sending','uncertain','review'].includes(m.status));if(shipment.invoiceStatus==='issued'){cell.append(el('p','Afsluttet · faktura registreret'));}else if(sentBasis||queued){const status=(sentBasis||queued).status;cell.append(el('p',status==='sent'?'Grundlag sendt · afventer faktura fra bogholder':status==='review'?'Grundlag klar · se afsendelsen nedenfor':'Afsendelse skal afstemmes · send ikke igen'));}else if(shipment.invoiceStatus!=='issued')cell.append(button('Klargør grundlag til bogholder',()=>action({action:'accountant',shipmentKey:shipment.key})));row.append(cell);table.append(row);}body.append(table);
  const billing=el('details'),bf=el('form');bf.className='document-fields';billing.append(el('summary','Ret faktureringsoplysninger'),el('p','Ændrer ordren. Allerede udstedte bilag bevares uændret.'),bf);for(const [key,label] of [['company','Fakturamodtager'],['street','Adresse'],['postalCode','Postnummer'],['city','By'],['country','Landekode'],['email','Faktura-e-mail'],['cvr','CVR'],['ean','EAN'],['reference','Reference']]){const i=field(bf,label,key,data.billing[key]||(key==='country'?'DK':''));i.required=!['cvr','ean','reference'].includes(key);}bf.append(el('button','Gem fakturaoplysninger på ordren'));bf.onsubmit=e=>{e.preventDefault();action({action:'billing',billing:Object.fromEntries(new FormData(bf))});};accounting.append(billing);
  const docs=el('details');docs.append(el('summary','Fakturaer, kreditnotaer og senere fakturaønsker'));
  for(const d of data.documents){const p=el('p'),a=el('a',`${d.kind==='credit'?'Kreditnota':d.kind==='replacement'?'Senere fuld faktura':'Faktura'} ${d.number} · ${money(d.total)}`);a.href=url+'?document='+d.id;p.append(a);if(d.kind==='credit')p.append(button('Refundér mod kreditnota',()=>{const value=prompt('Beløb i kroner. Refundering lukker for yderligere hævninger på samme transaktion.');if(value===null)return;const amount=Math.round(Number(value.replace(',','.'))*100);if(confirm('Tilbagebetal '+money(amount)+'?'))action({action:'payment',kind:'refund',amount,documentId:d.id,key:'refund:'+d.id+':'+s.refunded});}));docs.append(p);}
  const form=el('form');form.className='document-fields';const kind=el('select');kind.name='kind';for(const [value,title] of [['invoice','Faktura for leverance'],['credit','Kreditnota'],['replacement','Senere fuld faktura – samme salg']]){const opt=el('option',title);opt.value=value;kind.append(opt);}form.append(kind);
  field(form,'Fakturanummer / kreditnotanummer','number');field(form,'Aftalt nummerserie','series',data.configuration.series||'');field(form,'Bilagsdato','date',new Date().toISOString().slice(0,10),'date');field(form,'Beløb inkl. moms (kr.)','total');field(form,'Moms (kr.)','vat');
  const shipment=el('select');shipment.name='shipmentKey';const none=el('option','Vælg leverance');none.value='';shipment.append(none);for(const row of data.shipments){const opt=el('option',row.shipDate.slice(0,10)+' · '+money(row.total));opt.value=row.key;shipment.append(opt);}form.append(shipment);
  const original=el('select');original.name='original';const no=el('option','Oprindelig faktura ved korrektion');no.value='';original.append(no);for(const d of data.documents.filter(d=>d.kind==='invoice')){const opt=el('option',d.number);opt.value=d.id;original.append(opt);}form.append(original);field(form,'Begrundelse ved korrektion','reason').required=false;const file=field(form,'Udstedt PDF fra e-conomic','pdf','','file');file.accept='application/pdf';form.append(el('button','Registrér udstedt bilag'));form.onsubmit=async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(form));const bytes=new Uint8Array(await file.files[0].arrayBuffer());if(bytes.length>10*1024*1024)throw Error('PDF må højst være 10 MB.');let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await action({...v,action:'register_document',original:v.original||undefined,shipmentKey:v.shipmentKey||undefined,total:Math.round(Number(v.total.replace(',','.'))*100),vat:Math.round(Number(v.vat.replace(',','.'))*100),pdf:btoa(binary)});}catch(e){feedback.textContent=e.message;}};docs.append(form,button('Registrér ønske om fuld faktura',()=>{const reason=prompt('Kundens ønske / reference');if(reason)action({action:'request_full_invoice',reason});}));accounting.append(docs);
  const log=el('details');log.append(el('summary','Betalinger og afsendelser'));for(const p of data.payments)log.append(el('p',`${p.type==='capture'?'Hævning':'Refundering'} · ${money(p.amount)} · Quickpay ${p.paymentId}/${p.id}`));for(const op of data.operations){const p=el('p',`${op.kind} · ${money(op.amount)} · ${labels[op.status]||op.status} · ${op.error||''}`);if(op.status==='failed')p.append(button('Nyt forsøg efter afklaring',()=>{if(confirm('Start et nyt betalingsforsøg på '+money(op.amount)+' efter den bekræftede afvisning?'))action({action:'payment',kind:op.kind,amount:op.amount,documentId:op.documentId,key:'manual:'+crypto.randomUUID()});}));log.append(p);}for(const m of data.mail){const p=el('p',`${m.kind==='accountant_basis'?'Fakturagrundlag':'Betalingskvittering'} · ${m.to} · ${labels[m.status]||m.status}`);if(m.status!=='sent')p.append(button('Gennemgå afsendelse',()=>{const uncertain=['sending','uncertain'].includes(m.status);if(confirm(uncertain?'Har du kontrolleret mailkontoen og bekræftet, at beskeden IKKE er sendt?':'Send beskeden til '+m.to+'?'))action({action:'receipt',key:m.key,confirmedNotSent:uncertain});}));log.append(p);}body.append(log);
  const settlement=el('details'),sf=el('form');sf.className='document-fields';settlement.append(el('summary','Registrér afregning fra Clearhaus / bank'),el('p','Angiv kun denne ordres andel af afregningen. Beløb er i kroner. Quickpay-gebyrer og indsigelser skal specificeres i bemærkningen og bogføres særskilt efter bogholderens opsætning.'),sf);for(const [key,label] of [['reference','Afregningsreference'],['bankReference','Bankreference'],['economicReference','Bogføringsreference'],['gross','Kundebetalinger'],['refunds','Refunderinger'],['fees','Clearhaus-gebyrer'],['adjustments','Øvrige reguleringer (+/-)'],['held','Tilbageholdt (+) / frigivet (-)'],['bank','Bankudbetaling'],['notes','Specifikation / bemærkning']])field(sf,label,key,['gross','refunds','fees','adjustments','held','bank'].includes(key)?'0':'');sf.append(el('button','Registrér afstemt afregning'));sf.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(sf));for(const k of ['gross','refunds','fees','adjustments','held','bank'])v[k]=Math.round(Number(v[k].replace(',','.'))*100);action({action:'settlement',settlement:v});};accounting.append(settlement);const exportLink=el('a','Hent afstemningsgrundlag (JSON)'),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const objectURL=URL.createObjectURL(blob);exportLink.href=objectURL;exportLink.download='Smerch-afstemning-'+data.orderId+'.json';exportLink.onclick=()=>setTimeout(()=>URL.revokeObjectURL(objectURL),60000);accounting.append(exportLink);body.append(accounting);
 }catch(e){feedback.textContent=e.message;}}
 return root;
}
